{"command":"cd /workspace && cat > location.go <<'EOF'
package gowsdl

import (
	"net/url"
	"path/filepath"
)

// Location represents the location of a WSDL or XSD document. It can either
// be a URL or an absolute path in the local file system.
type Location struct {
	u *url.URL
	f string
}

// ParseLocation parses a raw location into a Location. Relative file paths are
// turned into absolute ones.
func ParseLocation(rawloc string) (*Location, error) {
	u, _ := url.Parse(rawloc)
	if u.Scheme != "" {
		return &Location{u: u}, nil
	}

	absPath, err := filepath.Abs(rawloc)
	if err != nil {
		return nil, err
	}
	return &Location{f: absPath}, nil
}

// Parse resolves a reference relative to the current location.
func (r *Location) Parse(ref string) (*Location, error) {
	if r.u != nil {
		u, err := r.u.Parse(ref)
		if err != nil {
			return nil, err
		}
		return &Location{u: u}, nil
	}

	u, _ := url.Parse(ref)
	if u.Scheme != "" {
		return &Location{u: u}, nil
	}

	if filepath.IsAbs(ref) {
		return &Location{f: ref}, nil
	}
	return &Location{f: filepath.Join(filepath.Dir(r.f), ref)}, nil
}

// IsFile reports whether the location points to the local file system.
func (r *Location) IsFile() bool {
	return r.u == nil
}

// IsURL reports whether the location is a URL.
func (r *Location) IsURL() bool {
	return r.u != nil
}

// String returns the textual representation of the location.
func (r *Location) String() string {
	if r.IsFile() {
		return r.f
	}
	return r.u.String()
}
EOF
echo ok"}

