// findNameByType looks for elements whose type is the given one and returns
// the element name, provided that all the matching elements share the same
// name. Otherwise the type name itself is returned.
func (t *traverser) findNameByType(name string) string {
	found := ""
	ambiguous := false

	var visit func(elements []*XSDElement)
	var visitComplexType func(ct *XSDComplexType)

	visit = func(elements []*XSDElement) {
		for _, el := range elements {
			if el == nil {
				continue
			}
			if el.Type != "" && stripns(el.Type) == name {
				if found == "" {
					found = el.Name
				} else if found != el.Name {
					ambiguous = true
				}
			}
			if el.ComplexType != nil {
				visitComplexType(el.ComplexType)
			}
		}
	}

	visitComplexType = func(ct *XSDComplexType) {
		if ct == nil {
			return
		}
		visit(ct.Sequence)
		visit(ct.Choice)
		visit(ct.SequenceChoice)
		visit(ct.All)
		visit(ct.ComplexContent.Extension.Sequence)
		visit(ct.ComplexContent.Extension.Choice)
		visit(ct.ComplexContent.Extension.SequenceChoice)
	}

	for _, schema := range t.all {
		visit(schema.Elements)
		for _, ct := range schema.ComplexTypes {
			visitComplexType(ct)
		}
	}

	if found == "" || ambiguous {
		return name
	}
	return found
}
