		log.Fatalln("Output file cannot be the same WSDL file")
	}

	// load wsdl
	gowsdl, err := gen.NewGoWSDL(wsdlPath, *pkg, *insecure, *makePublic)
	if err != nil {
		log.Fatalln(err)
	}

	// generate code
	gocode, err := gowsdl.Start()
	if err != nil {
		log.Fatalln(err)
	}

	pkg := filepath.Join(*dir, *pkg)
	err = os.Mkdir(pkg, 0744)

	fd, err := os.Create(filepath.Join(pkg, *outFile))
	if err != nil {
		log.Fatalln(err)
	}
	defer fd.Close()

	data := new(bytes.Buffer)
	data.Write(gocode["header"])
	data.Write(gocode["types"])
	data.Write(gocode["operations"])
	data.Write(gocode["soap"])

	// go fmt the generated code
	source, err := format.Source(data.Bytes())
	if err != nil {
		fd.Write(data.Bytes())
		log.Fatalln(err)
	}

	fd.Write(source)

	// server
	serverFd, err := os.Create(filepath.Join(pkg, "server"+*outFile))
	if err != nil {
		log.Fatalln(err)
	}
	defer serverFd.Close()

	serverData := new(bytes.Buffer)
	serverData.Write(gocode["server_header"])
	serverData.Write(gocode["server_wsdl"])
	serverData.Write(gocode["server"])

	serverSource, err := format.Source(serverData.Bytes())
	if err != nil {
		serverFd.Write(serverData.Bytes())
		log.Fatalln(err)
	}
	serverFd.Write(serverSource)

	log.Println("Done 👍")
}
EOF
echo ok

