package gowsdl

import "strings"

// Method setNS sets (and returns) the currently active XML namespace.
func (g *GoWSDL) setNS(ns string) string {
	g.currentNamespace = ns
	return ns
}

// Method getNS returns the currently active XML namespace.
func (g *GoWSDL) getNS() string {
	return g.currentNamespace
}

// elemName computes the Go identifier used for an element field.
func (g *GoWSDL) elemName(el *XSDElement) string {
	if el.Name == "" {
		return "EmptyString"
	}
	return g.makePublicFn(replaceReservedWords(el.Name))
}

// attrName computes the Go identifier used for an attribute field.
func attrName(attr *XSDAttribute) string {
	return makePublic(normalize(attr.Name))
}

// attrType computes the Go type of an attribute.
func attrType(attr *XSDAttribute) string {
	if attr.Type != "" {
		return toGoType(attr.Type, false)
	}
	if attr.SimpleType != nil && attr.SimpleType.Restriction.Base != "" {
		return toGoType(attr.SimpleType.Restriction.Base, false)
	}
	return "string"
}

// inlineSimpleType computes the Go type of an element with an anonymous simple type.
func inlineSimpleType(st *XSDSimpleType) string {
	if st.List.ItemType != "" {
		return "[]" + toGoType(st.List.ItemType, false)
	}
	return toGoType(st.Restriction.Base, false)
}

// resolveAttributeRefs replaces attribute references with the referenced
// global attribute declarations.
func (g *GoWSDL) resolveAttributeRefs() {
	lookup := func(ref string) *XSDAttribute {
		r := strings.Split(ref, ":")
		if len(r) != 2 {
			return nil
		}
		for _, schema := range g.wsdl.Types.Schemas {
			for _, attr := range schema.Attributes {
				if attr.Name == r[1] {
					return attr
				}
			}
		}
		return nil
	}

	var fixAttrs func(attrs []*XSDAttribute)
	fixAttrs = func(attrs []*XSDAttribute) {
		for _, attr := range attrs {
			if attr.Ref == "" {
				continue
			}
			found := lookup(attr.Ref)
			if found == nil {
				attr.Name = ""
				attr.Type = ""
				attr.SimpleType = nil
				continue
			}
			attr.Name = found.Name
			attr.Type = found.Type
			attr.SimpleType = found.SimpleType
		}
	}

	var fixElements func(elements []*XSDElement)
	var fixComplexType func(ct *XSDComplexType)

	fixElements = func(elements []*XSDElement) {
		for _, el := range elements {
			if el.ComplexType != nil {
				fixComplexType(el.ComplexType)
			}
		}
	}

	fixComplexType = func(ct *XSDComplexType) {
		fixAttrs(ct.Attributes)
		fixAttrs(ct.ComplexContent.Extension.Attributes)
		fixAttrs(ct.SimpleContent.Extension.Attributes)
		fixElements(ct.Sequence)
		fixElements(ct.Choice)
		fixElements(ct.SequenceChoice)
		fixElements(ct.All)
		fixElements(ct.ComplexContent.Extension.Sequence)
		fixElements(ct.ComplexContent.Extension.Choice)
		fixElements(ct.ComplexContent.Extension.SequenceChoice)
	}

	for _, schema := range g.wsdl.Types.Schemas {
		fixElements(schema.Elements)
		for _, ct := range schema.ComplexTypes {
			fixComplexType(ct)
		}
	}
}
