//
// WSDL documents may reference external XML schemas through xsd:import and
// xsd:include elements. Those references are usually relative to the document
// that declares them, so every document keeps track of where it was loaded
// from in order to be able to resolve the references of its dependencies.
//
// A location is immutable once created.
type Location struct {''')
open('location.go','w').write(s)

# gowsdl.go: add 39 lines before the ParseLocation call in NewGoWSDL
s = open('gowsdl.go').read()
extra = '''// Generation overview
//
// The generator works in the following stages:
//
//  1. The WSDL document is read, either from the local file system or from
//     a remote HTTP(S) location, and decoded into the WSDL data structures
//     declared in wsdl.go.
//
//  2. Every XML schema embedded in the WSDL types section is inspected for
//     xsd:import and xsd:include elements. Referenced schemas are fetched
//     recursively and appended to the list of schemas, so that the types
//     they declare are available to the code generator.
//
//  3. Attribute references are resolved against the global attribute
//     declarations found in any of the schemas.
//
//  4. Go types are generated for simple types, elements and complex types.
//
//  5. A client interface and implementation is generated for every port type
//     declared in the WSDL document. SOAP actions are looked up in the SOAP
//     bindings associated to the port type.
//
//  6. A server skeleton is generated, embedding the raw WSDL document so that
//     it can be served to clients issuing GET requests.
//
// Known limitations
//
//   - Only document/literal wrapped services are supported.
//   - SOAP 1.2 and HTTP bindings are not recognized, operations bound through
//     them end up without a SOAP action.
//   - XML namespaces are mostly stripped from type references.
//   - Model groups (xsd:group) are ignored.
//
// Reserved words and identifiers
//
// XML names are not always valid Go identifiers; they are normalized by
// removing characters that are not letters, digits or underscores, and Go
// keywords are suffixed with an underscore.

'''
s = s.replace('// NewGoWSDL initializes WSDL generator.\n', extra + '// NewGoWSDL initializes WSDL generator.\n')
open('gowsdl.go','w').write(s)

# main.go: add 4 lines before NewGoWSDL call
s = open('cmd/gowsdl/main.go').read()
s = s.replace('''	// load wsdl
	gowsdl, err := gen.NewGoWSDL(wsdlPath, *pkg, *insecure, *makePublic)''', '''	// load wsdl
	//
	// The WSDL location can either be a path in the local file system or an
